        'Ш': { type: 'prop', script: 'cor_globe', hint: 'Брошенные вещи', if: 'cor_deeper&!cor_globe', tile: 'X' },
        'Б': { type: 'npc', who: 'bronya', name: 'Эхо Брони', dir: 'down', if: 'cor_globe&!cor_hubs', text: '...Ты до сих пор не сказала мне, что это за место, матушка.', echo: true },
        'К': { type: 'npc', who: 'cocolia', name: 'Эхо Коколии', dir: 'down', if: 'cor_globe&!cor_hubs', text: 'Семьсот лет назад это была северная граница Белобога.', bark: ['Б|...Ты до сих пор не сказала мне, что это за место, матушка.', '|Семьсот лет назад это была северная граница Белобога, здесь случилась древняя битва. Именно здесь Алиса Рэнд возглавила первый отряд Среброгривых Стражей в сопротивлении Легиону.', '|Теперь... это не что иное, как заброшенный коридор, наполненный отголосками эха Старого света. В день, когда обещание будет выполнено... эти руины станут началом нового мира.', 'Б|...Матушка, ты действительно веришь обещанию Стелларона? Он вызвал метель за нашими стенами и открыл дверь Фрагментума...', '|С того момента, как эти незваные гости спустились с неба, этому миру был вынесен смертный приговор. Но Стелларон... сохранил для нас нить надежды.', '|Когда обещание будет выполнено, Броня... нам больше не придётся тратить свои жизни на охрану этой пустоши.'], echo: true },
        'Ъ': { type: 'trigger', script: 'cor_gate', once: 'cor_gate', if: 'cor_globe&!cor_gate' },
        'А': { type: 'prop', script: 'cor_hub0', hint: 'Центр энергоснабжения механизмов', tile: 'X' },
        'Г': { type: 'prop', script: 'cor_hub1', hint: 'Центр энергоснабжения механизмов', tile: 'X' },
